", "new_string": "    def subtotal(self):
        return sum(cents for _, cents in self.lines)

    def apply_code(self, code):
        if code != "SAVE10":
            raise ValueError(f"unknown discount code: {code}")
        self.discount_code = code

    def discount(self):
        if self.discount_code != "SAVE10":
            return 0
        return percent(self.subtotal(), 10)

    def total(self):
        return self.subtotal() - self.discount()

    def render(self):
